ALTER TABLE public.user_roles ADD COLUMN platform_owner boolean NOT NULL DEFAULT false;
CREATE FUNCTION public.is_platform_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND platform_owner) $$;
CREATE FUNCTION public.guard_platform_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND (TG_OP='INSERT' AND NEW.platform_owner OR TG_OP='UPDATE' AND NEW.platform_owner IS DISTINCT FROM OLD.platform_owner) AND NOT public.is_platform_owner() THEN RAISE EXCEPTION 'Platform access must be granted by a platform owner'; END IF; RETURN NEW; END $$;
CREATE TRIGGER user_roles_guard_platform BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.guard_platform_owner();
CREATE TABLE public.document_masters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), name text NOT NULL, kind text NOT NULL DEFAULT 'contract' CHECK(kind IN('contract','checklist','terms','other')), state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','active','archived')), trade text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', items text[] NOT NULL DEFAULT '{}', source_document_id uuid REFERENCES public.company_documents(id) ON DELETE RESTRICT, revision int NOT NULL DEFAULT 1, cloned_from uuid REFERENCES public.document_masters(id) ON DELETE RESTRICT, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.document_masters TO authenticated; GRANT ALL ON public.document_masters TO service_role;
ALTER TABLE public.document_masters ENABLE ROW LEVEL SECURITY;
CREATE POLICY masters_read ON public.document_masters FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND (state='active' OR public.is_company_manager()));
CREATE POLICY masters_write ON public.document_masters FOR ALL TO authenticated USING(company_id=public.current_company_id() AND public.has_company_role('admin')) WITH CHECK(company_id=public.current_company_id() AND public.has_company_role('admin'));
ALTER TABLE public.contract_types ADD COLUMN base_document_id uuid REFERENCES public.document_masters(id) ON DELETE RESTRICT, ADD COLUMN checklist_document_id uuid REFERENCES public.document_masters(id) ON DELETE RESTRICT, ADD COLUMN lifecycle text NOT NULL DEFAULT 'active' CHECK(lifecycle IN('draft','active','archived'));
ALTER TABLE public.maintenance_agreements ADD COLUMN terms_snapshot jsonb NOT NULL DEFAULT '{}';
CREATE TABLE public.document_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,site_id uuid REFERENCES public.sites(id) ON DELETE RESTRICT,master_id uuid NOT NULL REFERENCES public.document_masters(id) ON DELETE RESTRICT,snapshot jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.document_attachments TO authenticated; GRANT ALL ON public.document_attachments TO service_role;
ALTER TABLE public.document_attachments ENABLE ROW LEVEL SECURITY;
CREATE POLICY attachments_read ON public.document_attachments FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.is_company_manager());
CREATE POLICY attachments_add ON public.document_attachments FOR INSERT TO authenticated WITH CHECK(company_id=public.current_company_id() AND public.has_company_role('admin'));
CREATE POLICY attachments_remove ON public.document_attachments FOR DELETE TO authenticated USING(company_id=public.current_company_id() AND public.has_company_role('admin'));
CREATE FUNCTION public.guard_document_master() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF TG_OP='DELETE' THEN IF OLD.state<>'draft' OR EXISTS(SELECT 1 FROM public.document_attachments WHERE master_id=OLD.id) OR EXISTS(SELECT 1 FROM public.contract_types WHERE base_document_id=OLD.id OR checklist_document_id=OLD.id) THEN RAISE EXCEPTION 'This document is in use or was published; archive it instead'; END IF; RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND OLD.state<>'draft' AND (NEW.body IS DISTINCT FROM OLD.body OR NEW.items IS DISTINCT FROM OLD.items OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.trade IS DISTINCT FROM OLD.trade OR NEW.name IS DISTINCT FROM OLD.name OR NEW.state='draft') THEN RAISE EXCEPTION 'Clone a published document before editing'; END IF;
 IF NEW.source_document_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.company_documents WHERE id=NEW.source_document_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Source is outside this company'; END IF;
 IF NEW.cloned_from IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.document_masters WHERE id=NEW.cloned_from AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Clone is outside this company'; END IF;
 IF NEW.state='active' AND (trim(NEW.name)='' OR (NEW.kind='checklist' AND cardinality(NEW.items)=0) OR (NEW.kind<>'checklist' AND trim(NEW.body)='')) THEN RAISE EXCEPTION 'Complete the document before publishing'; END IF;
 NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER document_master_guard BEFORE INSERT OR UPDATE OR DELETE ON public.document_masters FOR EACH ROW EXECUTE FUNCTION public.guard_document_master();
CREATE FUNCTION public.snapshot_document_attachment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.document_masters; BEGIN SELECT * INTO d FROM public.document_masters WHERE id=NEW.master_id AND company_id=NEW.company_id AND state='active'; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.clients WHERE id=NEW.client_id AND company_id=NEW.company_id) OR (NEW.site_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sites WHERE id=NEW.site_id AND client_id=NEW.client_id AND company_id=NEW.company_id)) THEN RAISE EXCEPTION 'Choose an active company document and valid client/site'; END IF; NEW.snapshot=to_jsonb(d)-'created_by'-'source_document_id'; RETURN NEW; END $$;
CREATE TRIGGER document_attachment_snapshot BEFORE INSERT ON public.document_attachments FOR EACH ROW EXECUTE FUNCTION public.snapshot_document_attachment();
CREATE FUNCTION public.guard_contract_documents() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF TG_OP='DELETE' THEN IF EXISTS(SELECT 1 FROM public.maintenance_agreements WHERE contract_type_id=OLD.id) THEN RAISE EXCEPTION 'Clients are assigned to this tier; archive it instead'; END IF; RETURN OLD; END IF;
 IF NEW.base_document_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.document_masters WHERE id=NEW.base_document_id AND company_id=NEW.company_id AND kind='contract' AND state='active') THEN RAISE EXCEPTION 'Choose an active contract for this company'; END IF;
 IF NEW.checklist_document_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.document_masters WHERE id=NEW.checklist_document_id AND company_id=NEW.company_id AND kind='checklist' AND state='active') THEN RAISE EXCEPTION 'Choose an active checklist for this company'; END IF; RETURN NEW; END $$;
CREATE TRIGGER contract_document_guard BEFORE INSERT OR UPDATE OR DELETE ON public.contract_types FOR EACH ROW EXECUTE FUNCTION public.guard_contract_documents();
CREATE FUNCTION public.snapshot_agreement_documents() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.contract_types; BEGIN IF NOT EXISTS(SELECT 1 FROM public.clients WHERE id=NEW.client_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Client is outside this company'; END IF; IF NEW.contract_type_id IS NOT NULL THEN SELECT * INTO t FROM public.contract_types WHERE id=NEW.contract_type_id AND company_id=NEW.company_id AND lifecycle='active'; IF NOT FOUND THEN RAISE EXCEPTION 'Choose an active company tier'; END IF; NEW.terms_snapshot=jsonb_build_object('tier',to_jsonb(t),'contract',(SELECT to_jsonb(d)-'created_by' FROM public.document_masters d WHERE id=t.base_document_id),'checklist',(SELECT to_jsonb(d)-'created_by' FROM public.document_masters d WHERE id=t.checklist_document_id)); END IF; RETURN NEW; END $$;
CREATE TRIGGER agreement_document_snapshot BEFORE INSERT ON public.maintenance_agreements FOR EACH ROW EXECUTE FUNCTION public.snapshot_agreement_documents();
CREATE TABLE public.platform_products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,app_url text NOT NULL DEFAULT '',currency text NOT NULL DEFAULT 'EUR',trial_days int NOT NULL DEFAULT 60 CHECK(trial_days BETWEEN 0 AND 3650),modules text[] NOT NULL DEFAULT '{core}',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.platform_products TO authenticated; GRANT ALL ON public.platform_products TO service_role; ALTER TABLE public.platform_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_read ON public.platform_products FOR SELECT TO authenticated USING(true); CREATE POLICY products_manage ON public.platform_products FOR ALL TO authenticated USING(public.is_platform_owner()) WITH CHECK(public.is_platform_owner());
CREATE TABLE public.platform_catalog(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.platform_products(id) ON DELETE RESTRICT,name text NOT NULL,kind text NOT NULL DEFAULT 'plan' CHECK(kind IN('plan','pack')),state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','active','archived')),sort_order int NOT NULL DEFAULT 0,monthly_price numeric NOT NULL DEFAULT 0 CHECK(monthly_price>=0),quarterly_price numeric NOT NULL DEFAULT 0 CHECK(quarterly_price>=0),yearly_price numeric NOT NULL DEFAULT 0 CHECK(yearly_price>=0),included_seats int NOT NULL DEFAULT 4 CHECK(included_seats>=0),modules text[] NOT NULL DEFAULT '{core}',branding_required boolean NOT NULL DEFAULT false,referral_reward numeric NOT NULL DEFAULT 0 CHECK(referral_reward>=0),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.platform_catalog TO authenticated; GRANT ALL ON public.platform_catalog TO service_role; ALTER TABLE public.platform_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON public.platform_catalog FOR SELECT TO authenticated USING(state='active' OR public.is_platform_owner()); CREATE POLICY catalog_manage ON public.platform_catalog FOR ALL TO authenticated USING(public.is_platform_owner()) WITH CHECK(public.is_platform_owner());
CREATE TABLE public.platform_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.platform_products(id) ON DELETE RESTRICT,company_id uuid REFERENCES public.companies(id) ON DELETE RESTRICT,tenant_name text NOT NULL DEFAULT '',external_tenant_id text,plan_id uuid REFERENCES public.platform_catalog(id) ON DELETE RESTRICT,status text NOT NULL DEFAULT 'trial' CHECK(status IN('trial','active','read_only','cancelled','legacy')),cadence text NOT NULL DEFAULT 'monthly' CHECK(cadence IN('monthly','quarterly','yearly')),agreed_price numeric NOT NULL DEFAULT 0 CHECK(agreed_price>=0),seats int NOT NULL DEFAULT 4 CHECK(seats>=0),trial_ends_at timestamptz NOT NULL DEFAULT now()+interval '60 days',pack_ids uuid[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(product_id,company_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.platform_subscriptions TO authenticated; GRANT ALL ON public.platform_subscriptions TO service_role; ALTER TABLE public.platform_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscriptions_read ON public.platform_subscriptions FOR SELECT TO authenticated USING(public.is_platform_owner() OR company_id=public.current_company_id() AND public.has_company_role('admin')); CREATE POLICY subscriptions_manage ON public.platform_subscriptions FOR ALL TO authenticated USING(public.is_platform_owner()) WITH CHECK(public.is_platform_owner());
CREATE TABLE public.platform_overrides(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subscription_id uuid NOT NULL REFERENCES public.platform_subscriptions(id) ON DELETE CASCADE,module text NOT NULL,enabled boolean NOT NULL DEFAULT true,starts_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz NOT NULL DEFAULT now()+interval '1 month',reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.platform_overrides TO authenticated; GRANT ALL ON public.platform_overrides TO service_role; ALTER TABLE public.platform_overrides ENABLE ROW LEVEL SECURITY;
CREATE POLICY overrides_read ON public.platform_overrides FOR SELECT TO authenticated USING(public.is_platform_owner() OR EXISTS(SELECT 1 FROM public.platform_subscriptions s WHERE s.id=subscription_id AND s.company_id=public.current_company_id())); CREATE POLICY overrides_manage ON public.platform_overrides FOR ALL TO authenticated USING(public.is_platform_owner()) WITH CHECK(public.is_platform_owner());
CREATE TABLE public.platform_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.platform_products(id),kind text NOT NULL CHECK(kind IN('revenue','expense')),category text NOT NULL DEFAULT '',amount numeric NOT NULL DEFAULT 0 CHECK(amount>=0),entry_date date NOT NULL DEFAULT current_date,notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.platform_ledger TO authenticated; GRANT ALL ON public.platform_ledger TO service_role; ALTER TABLE public.platform_ledger ENABLE ROW LEVEL SECURITY; CREATE POLICY ledger_manage ON public.platform_ledger FOR ALL TO authenticated USING(public.is_platform_owner()) WITH CHECK(public.is_platform_owner());
CREATE TABLE public.platform_referrals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.platform_products(id),owner_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid DEFAULT public.current_company_id() REFERENCES public.companies(id),kind text NOT NULL DEFAULT 'customer' CHECK(kind IN('customer','affiliate','website')),code text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(18),'hex'),reward_type text NOT NULL DEFAULT 'credit' CHECK(reward_type IN('credit','cash')),reward_amount numeric NOT NULL DEFAULT 0 CHECK(reward_amount>=0),state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','active','archived')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.platform_referrals TO authenticated; GRANT ALL ON public.platform_referrals TO service_role; ALTER TABLE public.platform_referrals ENABLE ROW LEVEL SECURITY;
CREATE POLICY referrals_read ON public.platform_referrals FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.is_platform_owner()); CREATE POLICY referrals_request ON public.platform_referrals FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND company_id IS NOT DISTINCT FROM public.current_company_id() AND state='pending' AND reward_amount=0); CREATE POLICY referrals_manage ON public.platform_referrals FOR ALL TO authenticated USING(public.is_platform_owner()) WITH CHECK(public.is_platform_owner());
CREATE TABLE public.platform_conversions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),referral_id uuid NOT NULL REFERENCES public.platform_referrals(id),subscription_id uuid NOT NULL UNIQUE REFERENCES public.platform_subscriptions(id),state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','approved','rejected','paid')),reward_amount numeric NOT NULL DEFAULT 0 CHECK(reward_amount>=0),notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.platform_conversions TO authenticated; GRANT ALL ON public.platform_conversions TO service_role; ALTER TABLE public.platform_conversions ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversions_read ON public.platform_conversions FOR SELECT TO authenticated USING(public.is_platform_owner() OR EXISTS(SELECT 1 FROM public.platform_referrals r WHERE r.id=referral_id AND r.owner_id=auth.uid())); CREATE POLICY conversions_manage ON public.platform_conversions FOR ALL TO authenticated USING(public.is_platform_owner()) WITH CHECK(public.is_platform_owner());
CREATE TABLE public.platform_audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id uuid,entity text NOT NULL,entity_id uuid,action text NOT NULL,before_value jsonb,after_value jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.platform_audit TO authenticated; GRANT ALL ON public.platform_audit TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.platform_audit_id_seq TO service_role; ALTER TABLE public.platform_audit ENABLE ROW LEVEL SECURITY; CREATE POLICY audit_read ON public.platform_audit FOR SELECT TO authenticated USING(public.is_platform_owner());
CREATE FUNCTION public.audit_platform_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.platform_audit(actor_id,entity,entity_id,action,before_value,after_value) VALUES(auth.uid(),TG_TABLE_NAME,CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END,TG_OP,CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END,CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END); IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['platform_products','platform_catalog','platform_subscriptions','platform_overrides','platform_ledger','platform_referrals','platform_conversions'] LOOP EXECUTE format('CREATE TRIGGER platform_audit AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_platform_change()',t); END LOOP; END $$;
CREATE FUNCTION public.guard_platform_subscription() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.platform_products; pack uuid; BEGIN SELECT * INTO p FROM public.platform_products WHERE id=NEW.product_id; IF TG_OP='INSERT' AND NEW.status='trial' THEN NEW.trial_ends_at=now()+make_interval(days=>p.trial_days); END IF; IF NEW.plan_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.platform_catalog WHERE id=NEW.plan_id AND product_id=NEW.product_id AND kind='plan') THEN RAISE EXCEPTION 'Plan belongs to another product'; END IF; FOREACH pack IN ARRAY NEW.pack_ids LOOP IF NOT EXISTS(SELECT 1 FROM public.platform_catalog WHERE id=pack AND product_id=NEW.product_id AND kind='pack') THEN RAISE EXCEPTION 'Pack belongs to another product'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER subscription_guard BEFORE INSERT OR UPDATE ON public.platform_subscriptions FOR EACH ROW EXECUTE FUNCTION public.guard_platform_subscription();
CREATE FUNCTION public.company_module_access(_company uuid,_module text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.platform_subscriptions; o boolean; BEGIN SELECT ps.* INTO s FROM public.platform_subscriptions ps JOIN public.platform_products p ON p.id=ps.product_id WHERE ps.company_id=_company AND p.slug='fieldflow' LIMIT 1; IF NOT FOUND OR s.status='legacy' THEN RETURN true; END IF; IF s.status='trial' THEN RETURN s.trial_ends_at>now(); END IF; IF s.status<>'active' THEN RETURN false; END IF; SELECT enabled INTO o FROM public.platform_overrides WHERE subscription_id=s.id AND module=_module AND starts_at<=now() AND ends_at>now() ORDER BY created_at DESC LIMIT 1; IF FOUND THEN RETURN o; END IF; IF _module='core' THEN RETURN true; END IF; RETURN EXISTS(SELECT 1 FROM public.platform_catalog c WHERE (c.id=s.plan_id OR c.id=ANY(s.pack_ids)) AND _module=ANY(c.modules)); END $$;
CREATE FUNCTION public.guard_commercial_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; m text=TG_ARGV[0]; BEGIN c=CASE WHEN TG_OP='DELETE' THEN OLD.company_id ELSE NEW.company_id END; IF auth.uid() IS NOT NULL AND NOT public.company_module_access(c,m) THEN RAISE EXCEPTION 'Your company has read-only access to this module. Contact the office to renew or add a pack.'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; m text; BEGIN FOREACH t IN ARRAY ARRAY['job_sheets','jobsheet_time_logs','jobsheet_parts','jobs','shifts','clients','sites','assets','inventory_items','messages','leave_requests','contract_types','maintenance_agreements','document_masters','document_attachments','payroll_employees','payroll_payslips','payroll_year_rates'] LOOP IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name='company_id') THEN m=CASE WHEN t LIKE 'payroll_%' THEN 'payroll' WHEN t IN('document_masters','document_attachments') THEN 'digitization' WHEN t IN('contract_types','maintenance_agreements') THEN 'contracts' ELSE 'core' END; EXECUTE format('CREATE TRIGGER commercial_write_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_commercial_write(%L)',t,m); END IF; END LOOP; END $$;